(window.webpackJsonp=window.webpackJsonp||[]).push([[72],{510:function(t,s,_){"use strict";_.r(s);var v=_(11),e=Object(v.a)({},(function(){var t=this,s=t.$createElement,_=t._self._c||s;return _("ContentSlotsDistributor",{attrs:{"slot-key":t.$parent.slotKey}},[_("p",[_("font",{attrs:{size:"5"}},[t._v("我在"),_("RouterLink",{attrs:{to:"/_posts/刚性与弹性：一个长老与执事的按立问题.html"}},[t._v("《刚性与弹性：一个长老与执事的按立问题》")]),t._v("中提到，在教会的长老与执事的按立中，要坚持圣经标准的刚性，也要根据教会的处境保持一定的弹性。在整个过程中，候选人、具有属灵权柄的人（例如牧师）、教会其他会众，都需要根据这样所形成的标准，在神面前形成良心上的判断，来确定某个人（包括候选人确认自己）是否可以被立为长老或执事。")],1)],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("在这篇文章中，我想从另一个角度谈一谈这个问题。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("长老和执事是教会的两个主要职分。承担这样职分的人，属于教会的带领者。尤其是长老，具有属灵上治理的权柄，要确保教会行在真道上。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("既然教会是属神的，那么教会的带领者也一定是神所选出来、将教会委托给他们的，而不是人自己凭着血气来做的。也就是说，对于承担这个职分的人，一定是有神的呼召的。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("假设A弟兄被纳入了长老候选人的名单。这时候要处理两个问题：第一，由谁来确定A弟兄是否有呼召？第二，如何确定A弟兄是否有呼召？")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("我们先来谈第一个问题：由谁来确定？")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("首先的、最重要的，必然是A弟兄自己。神是呼召他，那么当然就会让他知道自己被呼召了。当神呼召摩西去埃及救出以色列人（出埃及记3~4章），呼召基甸去救以色列人脱离米甸人的手（士师记6章），他们当然首先要自己知道被呼召了。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("其次，是A弟兄周围的人，或者说他所在的教会，具体包括了教会的属灵领袖和其他会众。无论是教会的牧师还是会众，其作用都不是决定A弟兄是否被呼召（神才是决定者），而是识别他是否被呼召。保罗在哥林多前书16:15~16写到：“ 弟兄们，你们晓得司提反一家，是亚该亚初结的果子，并且他们专以服侍圣徒为念。 我劝你们顺服这样的人，并一切同工同劳的人。”这里虽然没有明确说司提反有长老的职分，但保罗劝哥林多教会要“顺服”他，这意味着保罗认可司提反具有属灵权柄（希伯来书13:17）。而司提反有什么特点呢？就是为神的道而劳苦，属于“一切同工同劳的人”中的一员，并且他这种“专以服侍圣徒为念”的品质，是哥林多教会所知道的。我们可以看到，无论是保罗还是哥林多教会，他们从司提反的身上，是能识别出神对司提反的呼召来的。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("接下来我们谈第二个问题，如何确定？")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("最低限度的，就是要判断A弟兄是否符合提摩太前书和提多书中的那些“圣经标准”。因为神不会自相矛盾，他设立了标准，就不会在一个人达不到这些标准的情况下，把他呼召成为教会的领袖。判断的方法，就是我在"),_("RouterLink",{attrs:{to:"/_posts/刚性与弹性：一个长老与执事的按立问题.html"}},[t._v("《刚性与弹性：一个长老与执事的按立问题》")]),t._v("中所说的，要形成自己在神面前的良心。")],1)],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("当然，这些是最低限度。在此基础上而有的其他更主观的印象，例如是否为服侍圣徒而甘心劳苦、是否为人的灵魂得救而不辞辛劳等等，往往也是神呼召的一个辨别标志。这方面网上的文章有很多了。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("因此，如果A弟兄自己认为他并不符合圣经标准，那么可以肯定他是没有被呼召的。即使教会的牧师觉得他符合，因而自认为识别出了这个被神呼召的人，那也只是错觉。这种情况下把A弟兄按立为长老，是违背神的心意的。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("下面举三个我经历过或听说过没有真实呼召的例子。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("例1：一位小教会的带领者，他总是与自己的妻子吵架，家庭关系非常差。其中当然有他的原因，也有他妻子的原因。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("管好自己的家才能管教会，这是一条神对教会长老的圣经标准（提前3:5）。虽然他并不是被按立的名义上的长老，但实际上就是这个教会的带领人，担负着长老的职责。既然管不好自己的家，无论是什么原因，说明神起码现在没有给他做长老的恩赐和呼召。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("我曾劝他把这个小教会并入到其他的教会中，由合格的人来带领兄弟姐妹，而他自己可以去从事其他的服侍，不一定非要自己搞个教会。但他觉得自己放不下这些兄弟姐妹、不放心其他人来带领，因此依旧我行我素。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("例2：一间比较大的教会，教会的牧师和妻子长期分居。这是明显的犯罪（哥林多前书7:5），因此这名牧师已经不符合“无可指责”的圣经标准（提前3:2）。但他觉得自己对会众有负担，也是在为主做工；甚至教会的会众也觉得牧师这样很不容易，可以谅解。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("上面这两个例子最终的结局是，这名带领人和这名牧师都分别发生了婚内出轨，使教会受到极大的损害。这当然是神对教会妥协他的道的管教。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("不符合神的标准，说明神没有呼召他；神没有呼召他，却自己要硬上，这就是凭血气做事，是犯罪；某个有形教会容忍犯罪，那要么被神弃绝，要么被神管教。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("下面这个例子有些不同，但性质是一样的，也属于缺乏呼召的情形。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("例3：某教会选立长老，牧师和教会会众都认为甲弟兄被呼召了（至少，他们认为他符合圣经标准），但甲弟兄他自己认为不符合（不是口头上的谦虚，而是真心认为自己不符合），但他又觉得既然大家都认为我可以，这或许就是神的呼召，我也就甘心承担这样的职分吧。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("同时，他还想到摩西（出埃及记3~4章）、基甸（士师记6章），他们当时也是认为自己的能力不够。但既然神呼召了他们，有什么好怕的呢！有神同在，对神要有信心。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("教会中的乙姐妹也鼓励他：既然牧师都说你可以，那么你就是可以。你自己认为是否符合那些圣经标准不重要；提摩太前书3、提多书1中那些标准是写给牧师的，他有决定权。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("教会中的丙弟兄也引出经文来证明：当年保罗在第一次宣教旅程中按立长老，肯定不需要那些教会和被按立人自己确认啊。他们是使徒，有属灵权柄。就像现在的牧师，他认为你被呼召了就是被呼召了。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("如何评价这件事情呢？")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("首先，甲弟兄所认识的这种“神的呼召”，是一种错觉。我在前面已经讲了，神的呼召，首先要的是他本人确定。确定的方法，最低限度的，就是他自己要面对神的标准形成良心上的认可。因为神不可能违背他的标准来呼召人。如果他自己无法在面对神的良心上，认可自己符合圣经标准，可以肯定神并没有呼召他。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("第二，甲弟兄使用摩西和基甸的故事来鼓励自己，是对经文的误用。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("一方面，在这经文上下文中，神并不是呼召摩西、基甸去做长老这个职分，而是呼召他们去执行在当时的历史情境中的一个具体使命，就是去把以色列人带出埃及、去打败米甸人。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("另一方面，从摩西、基甸的经文中，我们可以得出的教训是，对神的呼召，我们不要怕、不要搪塞、没有能力神也会给我们加能力，要对神有信心。神对每个人有不同的呼召，因此这些经文适用于任何服侍岗位。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("当甲弟兄用这些经文来鼓励自己时，他忽视了一个前置问题：就具体的某个事情来说，神到底是否呼召我们去干？还是说其实是出于自己的血气来干，然后拿这些经文给自己打气呢？对这个问题，仅仅去看摩西、基甸的相关经文，是得不出答案的。因为甲弟兄并不像摩西和基甸那样，是亲自面对面地见到神、直接从神那里得到信息。那这样怎么判断呢？还是要回到神在圣经中是怎么说的来：他现在要做长老，那么神对长老的标准是什么？退一步，即使他认为自己“听到了神的声音”，这声音到底是否来自于神，也要通过圣经来验证——还是要回到“圣经标准”中来，因为神不会自相矛盾。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("第三，乙姐妹是错解了圣经。提摩太前书和提多书被收录在圣经中，说明这两封信是神写给他历代教会的，让教会可以依此来识别出神所呼召的长老和执事的。教会当然就包括了牧师、其他会众，也当然包括了候选人本人。所以所有参与选立长老的人，都要依据这个标准来形成良心上的判断，而不仅仅是牧师。牧师有一定的属灵权柄，在其他会众出现分歧时，可以动用这个权柄来处理分歧。但牧师的权柄仅仅局限于识别谁有呼召，而不是决定谁有呼召。当候选人自己没有呼召的时候，说明神没有拣选他，牧师不能依据自己的权柄来替神做决定。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("第四，丙弟兄的解经也是错的。使徒行传里面并没有描述保罗第一次宣教过程中按立长老时，教会和被按立者本人的情形是怎样的。丙弟兄是把自己的臆想读进了圣经当中。如果按照这种读经方式可以猜测说，本人没有呼召也没关系，保罗认为有就行了；那也同样可以猜测说，如果当时本人认为自己没有呼召，保罗是不会按立他的。——事实上，根据我上文的讨论，这后一种“猜测”，才是正确的。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("有愿意带领教会、服侍大家的心是好的，保罗评价这是“羡慕善工”（提前3:1）。但光有这个不行。他紧接着说，“因此”、“既然如此”、“这样（原文中“οὖν”这个连词在和合本翻译中被漏掉了），做监督的应该符合接下来他说的这些标准。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("这些标准是某个人确定自己是否有呼召的最低的门槛，也是教会识别他有呼召的最低门槛。")])],1)])}),[],!1,null,null,null);s.default=e.exports}}]);